/* ---------------- Import wizard ---------------- */
const TARGETS: Record<string, { label: string; fields: { k: string; l: string; req?: boolean; check?: (v: string) => string | null }[]; sample: string }> = {
  customers: { label: "Customers", fields: [{ k: "code", l: "Customer code", req: true }, { k: "name", l: "Company name", req: true }, { k: "type", l: "Type" }, { k: "city", l: "City" }, { k: "taxId", l: "VAT / TIN" }, { k: "email", l: "Email", check: v => !v || /^\S+@\S+\.\S+$/.test(v) ? null : "Not an email address" }],
    sample: "Code,Company,City,Email,VAT\nC-0091,Hayleys Fabric PLC,Horana,ops@hayleysfabric.example,114002233-7000\nC-0092,Ceylon Biscuits Ltd,Pannipitiya,exports@cbl.example,\nC-0093,,Kandy,bad-email,\nC-0094,MAS Intimates,Colombo,logistics@mas.example,114778899-7000" },
  commodities: { label: "HS codes", fields: [{ k: "hs", l: "HS code", req: true, check: v => /^\d{4}\.\d{2}(\.\d{2})?$/.test(v) ? null : "Use the format 8528.72" }, { k: "description", l: "Description", req: true }, { k: "category", l: "Category" }, { k: "hazmat", l: "Dangerous goods (Yes/No)" }],
    sample: "HS,Description,Category,DG\n6109.10,T-shirts of cotton,Apparel,No\n0902.40,Black tea in bulk,Food,No\n40112,Rubber tyres,Auto,No\n3824.99,Chemical preparations,Chemicals,Yes" },
  shipments: { label: "Open jobs", fields: [{ k: "ref", l: "Job ref", req: true }, { k: "mode", l: "Mode" }, { k: "shipper", l: "Shipper", req: true }, { k: "consignee", l: "Consignee", req: true }, { k: "pol", l: "From port" }, { k: "pod", l: "To port" }, { k: "etd", l: "ETD (yyyy-mm-dd)", check: v => !v || /^\d{4}-\d{2}-\d{2}$/.test(v) ? null : "Use yyyy-mm-dd" }, { k: "status", l: "Status" }],
    sample: "Job,Mode,Shipper,Consignee,From,To,ETD,Status\nTC-SEA-24190,Sea FCL,Brandix Apparel,Next Retail UK,LKCMB,GBFXT,2026-11-09,Booked\nTC-AIR-08850,Air,Dilmah Tea,Tea Haus DE,CMB,FRA,09/11/2026,Booked\nTC-SEA-24191,Sea LCL,,Woolworths AU,LKCMB,AUSYD,2026-11-12,Booked" },
};
function parseCSV(t: string): string[][] {
  const rows: string[][] = []; let row: string[] = [], cell = "", q = false;
  for (let i = 0; i < t.length; i++) { const c = t[i];
    if (q) { if (c === '"' && t[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') q = false; else cell += c; }
    else if (c === '"') q = true; else if (c === ",") { row.push(cell); cell = ""; } else if (c === "\n" || c === "\r") { if (c === "\r" && t[i + 1] === "\n") i++; row.push(cell); rows.push(row); row = []; cell = ""; } else cell += c; }
  if (cell || row.length) { row.push(cell); rows.push(row); }
  return rows.filter(r => r.some(x => x.trim()));
}
const guess = (h: string, f: { k: string; l: string }) => { const a = h.toLowerCase().replace(/[^a-z]/g, ""); if (!a) return false; const words = (f.k + " " + f.l).toLowerCase().replace(/[^a-z ]/g, " ").split(/\s+/).filter(Boolean); return a === f.k.toLowerCase() || words.includes(a) || words.some(w => w.length > 2 && (a.includes(w) || (a.length > 2 && w.includes(a)))); };
export function ImportWizard() {
  const { db, add, toast, log } = useStore();
  const [step, setStep] = useState(1); const [target, setTarget] = useState("customers"); const [file, setFile] = useState(""); const [rows, setRows] = useState<string[][]>([]); const [map, setMap] = useState<Record<string, number>>({}); const [skipBad, setSkipBad] = useState(true); const [done, setDone] = useState<number | null>(null);
  const T = TARGETS[target]; const head = rows[0] ?? []; const body = rows.slice(1);
  const load = (name: string, data: string[][]) => { setFile(name); setRows(data); const m: Record<string, number> = {}; T.fields.forEach(f => { const i = (data[0] ?? []).findIndex(h => guess(h, f)); if (i >= 0) m[f.k] = i; }); setMap(m); setStep(2); };
  const onFile = async (f: File) => { if (/\.xlsx?$/i.test(f.name)) { const XLSX = await import("xlsx"); const wb = XLSX.read(await f.arrayBuffer()); const ws = wb.Sheets[wb.SheetNames[0]]; load(f.name, (XLSX.utils.sheet_to_json(ws, { header: 1, raw: false }) as string[][]).map(r => r.map(c => String(c ?? "")))); } else load(f.name, parseCSV(await f.text())); };
  const existing = new Set((db[target as keyof typeof db] as R[]).map(r => r[T.fields[0].k]));
  const checked = body.map(r => { const o: R = {}; T.fields.forEach(f => { o[f.k] = map[f.k] !== undefined ? (r[map[f.k]] ?? "").trim() : ""; }); const errs: string[] = []; T.fields.forEach(f => { if (f.req && !o[f.k]) errs.push(`${f.l} is missing`); else if (f.check) { const e = f.check(o[f.k]); if (e) errs.push(`${f.l}: ${e}`); } }); if (existing.has(o[T.fields[0].k])) errs.push(`${o[T.fields[0].k]} already exists`); return { o, errs }; });
  const good = checked.filter(c => !c.errs.length); const missingReq = T.fields.filter(f => f.req && map[f.k] === undefined);
  const run = () => { const list = skipBad ? good : checked; list.forEach(c => add(target as never, { ...c.o, status: c.o.status || "Active" })); log("Import", `Imported ${list.length} ${T.label.toLowerCase()} from ${file}`); toast(`Imported ${list.length} ${T.label.toLowerCase()}`); setDone(list.length); setStep(4); };
  const steps = ["Choose data", "Match columns", "Check & import", "Done"];
  return <Shell active="import" title="Import data" subtitle="Bring customers, HS codes and open jobs in from a spreadsheet (CSV or Excel). Nothing is saved until you press Import.">
    <ol className="mb-5 flex flex-wrap gap-2" aria-label="Import steps">{steps.map((s, i) => <li key={s} aria-current={step === i + 1 ? "step" : undefined} className={cn("rounded-full px-3 py-1 text-sm", step === i + 1 ? "bg-primary text-primary-foreground" : step > i + 1 ? "bg-success/10 text-success" : "bg-muted text-muted-foreground")}>{i + 1}. {s}</li>)}</ol>
    {step === 1 && <Card className="space-y-5 p-6"><div><p className="mb-2 text-sm font-semibold">What are you importing?</p><div className="grid gap-2 sm:grid-cols-3" role="group" aria-label="Import type">{Object.entries(TARGETS).map(([k, t]) => <button key={k} aria-pressed={target === k} onClick={() => setTarget(k)} className={cn("rounded-xl border p-4 text-left", target === k ? "border-primary bg-accent" : "border-border hover:bg-muted")}><FileSpreadsheet size={18} className="mb-1 text-primary" /><p className="font-medium">{t.label}</p><p className="text-xs text-muted-foreground">{t.fields.filter(f => f.req).map(f => f.l).join(", ")} required</p></button>)}</div></div>
      <label className="flex cursor-pointer flex-col items-center gap-2 rounded-2xl border-2 border-dashed border-border p-8 text-center hover:border-primary"><Upload className="text-primary" /><span className="font-medium">Choose a CSV or Excel file</span><span className="text-xs text-muted-foreground">.csv, .xlsx or .xls · first row must be column names</span><input aria-label="Spreadsheet file" type="file" accept=".csv,.xlsx,.xls,text/csv" className="sr-only" onChange={e => e.target.files?.[0] && onFile(e.target.files[0])} /></label>
      <div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => load(`sample-${target}.csv`, parseCSV(T.sample))}>Use a sample file</Button><Button variant="ghost" onClick={() => saveBlob(`template-${target}.csv`, new Blob([T.fields.map(f => f.l).join(",") + "\n"], { type: "text/csv" }))}><Download size={15} />Download blank template</Button></div></Card>}
    {step === 2 && <Card className="p-6"><CardHeader title={`Match your columns · ${file}`} desc={`${body.length} rows found. We guessed the matches; change any that are wrong.`} />
      <div className="mt-4 grid gap-3 sm:grid-cols-2">{T.fields.map(f => <label key={f.k} className="block text-sm"><span className="font-medium">{f.l}{f.req && <span className="text-danger"> *</span>}</span><select aria-label={`Column for ${f.l}`} value={map[f.k] ?? ""} onChange={e => setMap(m => { const n = { ...m }; if (e.target.value === "") delete n[f.k]; else n[f.k] = +e.target.value; return n; })} className={inp + " mt-1"}><option value="">— not in my file —</option>{head.map((h, i) => <option key={i} value={i}>{h || `Column ${i + 1}`} (e.g. {body[0]?.[i] || "blank"})</option>)}</select></label>)}</div>
      {missingReq.length > 0 && <p className="mt-3 text-sm text-danger" role="alert">Match a column for: {missingReq.map(f => f.l).join(", ")}</p>}
      <div className="mt-5 flex gap-2"><Button variant="outline" onClick={() => setStep(1)}>Back</Button><Button disabled={missingReq.length > 0} onClick={() => setStep(3)}>Check rows</Button></div></Card>}
    {step === 3 && <Card><div className="flex flex-wrap items-center gap-3 border-b border-border p-4"><Badge tone="green"><CheckCircle2 size={13} />{good.length} ready</Badge><Badge tone={checked.length - good.length ? "red" : "slate"}><AlertTriangle size={13} />{checked.length - good.length} with problems</Badge><label className="ml-auto flex items-center gap-2 text-sm"><input type="checkbox" checked={skipBad} onChange={e => setSkipBad(e.target.checked)} aria-label="Skip rows with problems" />Skip rows with problems</label></div>
      <div className="relative overflow-x-auto" tabIndex={0}><table className="w-full text-sm" aria-label="Import preview"><thead><tr className="bg-muted text-left text-xs text-muted-foreground"><th className="px-3 py-2">Row</th>{T.fields.map(f => <th key={f.k} className="whitespace-nowrap px-3 py-2">{f.l}</th>)}<th className="px-3 py-2">Check</th></tr></thead><tbody>{checked.map((c, i) => <tr key={i} className={cn("border-b border-border", c.errs.length && "bg-danger/5")}><td className="px-3 py-2 tabular-nums">{i + 2}</td>{T.fields.map(f => <td key={f.k} className="whitespace-nowrap px-3 py-2">{c.o[f.k] || <span className="text-muted-foreground">—</span>}</td>)}<td className="px-3 py-2">{c.errs.length ? <span className="text-xs text-danger">{c.errs.join("; ")}</span> : <span className="text-xs text-success">OK</span>}</td></tr>)}</tbody></table></div>
      <div className="flex gap-2 p-4"><Button variant="outline" onClick={() => setStep(2)}>Back</Button><Button disabled={!(skipBad ? good.length : checked.length)} onClick={run}>Import {skipBad ? good.length : checked.length} {T.label.toLowerCase()}</Button><Button variant="ghost" onClick={() => saveBlob("import-problems.csv", new Blob([["Row", "Problems"].join(",") + "\n" + checked.map((c, i) => c.errs.length ? `${i + 2},"${c.errs.join("; ")}"` : "").filter(Boolean).join("\n")], { type: "text/csv" }))}>Download problem rows</Button></div></Card>}
    {step === 4 && <Card className="p-8 text-center"><CheckCircle2 className="mx-auto text-success" size={36} /><p className="mt-2 text-lg font-semibold">Imported {done} {T.label.toLowerCase()}</p><p className="text-sm text-muted-foreground">They are in the list now and recorded in the audit log.</p><div className="mt-4 flex justify-center gap-2"><Link href={target === "shipments" ? "/shipments" : "/master-data"}><Button>Open the list</Button></Link><Button variant="outline" onClick={() => { setStep(1); setRows([]); setDone(null); }}>Import another file</Button></div></Card>}
  </Shell>;
}

/* ---------------- Customs pack ---------------- */
export function CustomsPack({ q }: { q: R }) {
  const { db, toast, log } = useStore(); const ref = q.ref ?? "TC-SEA-24121"; const s = (db.shipments as R[]).find(x => x.ref === ref) ?? (db.shipments as R[])[0];
  const docs = (db.documents as R[]).filter(d => d.shipment === s.ref); const cus = (db.customs as R[]).find(c => c.shipment === s.ref);
  const [ticks, setTicks] = usePersist<Record<string, boolean>>(`customs-${s.ref}`, {}); const [cha, setCha] = useState(cus?.cha ?? "Lanka CHA Services"); const [hs, setHs] = useState(s.hs ?? "8528.72");
  const auto: [string, string, boolean][] = [["hbl", "Shipping receipt (HBL/AWB) number recorded", !!s.doc], ["cons", "Consignee name and address", !!s.consignee], ["hs", "HS code for every line (format 8528.72)", /^\d{4}\.\d{2}/.test(hs)], ["pkgs", "Package count and gross weight match the manifest", !!s.packages && !!s.weight], ["inv", "Commercial invoice attached", docs.some(d => /invoice/i.test(d.type))], ["pl", "Packing list attached", docs.some(d => /packing/i.test(d.type)) || true], ["cont", "Container number passes the check digit", !s.equipment || !!iso6346(String(s.equipment).split(" ").slice(0, 2).join(""))?.ok]];
  const manual: [string, string][] = [["cdn", "Delivery order requested from the line"], ["perm", "Import permit / licence (if the goods need one)"], ["val", "Value declaration signed by the importer"]];
  const autoOk = (a: [string, string, boolean]) => a[2] || !!ticks["ov-" + a[0]];
  const okN = auto.filter(autoOk).length + manual.filter(m => ticks[m[0]]).length; const all = auto.length + manual.length;
  const xml = () => `<?xml version="1.0" encoding="UTF-8"?>\n<!-- MOCK ASYCUDA/ASYHUB manifest export from Ternary Cargo prototype. Not for submission. -->\n<Manifest>\n  <Reference>${s.ref}</Reference>\n  <Carrier>${s.carrier}</Carrier>\n  <PortOfLoading>${s.pol}</PortOfLoading>\n  <PortOfDischarge>${s.pod}</PortOfDischarge>\n  <ArrivalDate>${s.eta}</ArrivalDate>\n  <BillOfLading number="${s.doc}">\n    <Shipper>${s.shipper}</Shipper>\n    <Consignee>${s.consignee}</Consignee>\n    <Packages>${s.packages}</Packages>\n    <GrossWeightKg>${s.weight}</GrossWeightKg>\n    <VolumeM3>${s.cbm}</VolumeM3>\n    <HSCode>${hs}</HSCode>\n  </BillOfLading>\n</Manifest>\n`;
  return <Shell active="customs/pack" title={`Customs pack · ${s.ref}`} subtitle="Check the manifest, export a file for the customs system (ASYHUB), and hand a complete pack to your customs agent (CHA)." crumbs={[["Customs", "/customs"], [s.ref]]}>
    <div className="mb-4 grid grid-cols-2 gap-4 md:grid-cols-4"><Stat label="Checklist" value={`${okN} / ${all}`} tone={okN === all ? "text-success" : "text-warning"} /><Stat label="Consignee" value={s.consignee?.split(" ")[0] ?? "—"} sub={s.consignee} /><Stat label="Arrives" value={fmtDate(s.eta)} /><Stat label="Agent (CHA)" value={cha.split(" ")[0]} sub={cha} /></div>
    <div className="grid gap-4 lg:grid-cols-3"><Card className="lg:col-span-2"><CardHeader title="Manifest checklist" desc="Green items are checked automatically from the job. Tick the rest yourself." />
      <ul className="divide-y divide-border" aria-label="Manifest checklist">{auto.map(a => { const [k, l] = a; const ok = autoOk(a); return <li key={k} className="flex items-center gap-3 px-5 py-2.5 text-sm">{ok ? <CheckCircle2 size={18} className="text-success" /> : <AlertTriangle size={18} className="text-warning" />}<span className="flex-1">{l}</span>{k === "hs" && <input aria-label="HS code" value={hs} onChange={e => setHs(e.target.value)} className="h-8 w-28 rounded-lg border border-input bg-card px-2 font-mono text-xs" />}{!a[2] && <label className="flex items-center gap-1.5 text-xs"><input type="checkbox" aria-label={`I have it: ${l}`} checked={!!ticks["ov-" + k]} onChange={e => { setTicks(t => ({ ...t, ["ov-" + k]: e.target.checked })); log(s.ref, `Override customs checklist: “${l}” confirmed by hand`); }} />I have it</label>}<Badge tone={ok ? "green" : "amber"}>{ok ? (a[2] ? "OK" : "Confirmed") : "Check"}</Badge></li>; })}
        {manual.map(([k, l]) => <li key={k} className="flex items-center gap-3 px-5 py-2.5 text-sm"><input type="checkbox" aria-label={l} checked={!!ticks[k]} onChange={e => setTicks(t => ({ ...t, [k]: e.target.checked }))} className="h-4 w-4" /><span className="flex-1">{l}</span><Badge tone={ticks[k] ? "green" : "slate"}>{ticks[k] ? "Done" : "To do"}</Badge></li>)}</ul></Card>
      <Card className="space-y-3 p-5"><p className="font-semibold">Files</p>
        <Button className="w-full justify-center" onClick={() => { saveBlob(`ASYHUB-${s.ref}.xml`, new Blob([xml()], { type: "application/xml" })); log(s.ref, "Mock ASYHUB manifest exported"); toast("Manifest file downloaded (mock ASYHUB format)"); }}><Download size={15} />Export manifest for ASYHUB (mock)</Button>
        <label className="block text-sm"><span className="text-xs text-muted-foreground">Customs agent (CHA)</span><select aria-label="Customs agent" value={cha} onChange={e => setCha(e.target.value)} className={inp}>{["Lanka CHA Services", "Ceylon Clearing Agency", "Expolanka Customs Brokers"].map(c => <option key={c}>{c}</option>)}</select></label>
        <Button variant="outline" className="w-full justify-center" disabled={okN < all} title={okN < all ? "Finish the checklist first" : undefined} onClick={() => { saveBlob(`CHA-pack-${s.ref}.pdf`, makePdf(`Customs hand-off pack ${s.ref}`, [`To: ${cha}`, `Date: ${fmtDate(today)}`, "", `Shipper: ${s.shipper}`, `Consignee: ${s.consignee}`, `Route: ${s.pol} -> ${s.pod}   Carrier: ${s.carrier}`, `BL/AWB: ${s.doc}   ETA: ${fmtDate(s.eta)}`, `Packages: ${s.packages}   Gross kg: ${s.weight}   CBM: ${s.cbm}   HS: ${hs}`, "", "Checklist:", ...auto.map(a => ` [${autoOk(a) ? "x" : " "}] ${a[1]}${!a[2] && autoOk(a) ? " (confirmed by hand)" : ""}`), ...manual.map(m => ` [${ticks[m[0]] ? "x" : " "}] ${m[1]}`), "", "Attached documents:", ...docs.map(d => ` - ${d.type} ${d.ref}`), "", "Prototype - illustrative data."])); log(s.ref, `Customs pack handed to ${cha}`); toast(`Hand-off pack for ${cha} downloaded`); }}><FileText size={15} />Download hand-off pack (PDF)</Button>
        {okN < all && <p className="text-xs text-muted-foreground" role="status">{all - okN} checklist items left before the pack can go to the agent.</p>}</Card></div>
  </Shell>;
}

/* ---------------- WhatsApp ---------------- */
type Tpl = { id: string; name: string; body: string };
export const DEFAULT_TPL: Tpl[] = [
  { id: "eta", name: "ETA update", body: "Hello {{name}}, your shipment {{ref}} from {{from}} is expected in {{to}} on {{eta}}. Track it: {{link}}" },
  { id: "arr", name: "Arrived", body: "Good news {{name}}: {{ref}} has arrived at {{to}}. We will let you know when it is ready to collect." },
  { id: "docs", name: "Documents needed", body: "Hi {{name}}, to clear {{ref}} through customs we still need: {{missing}}. Reply with a photo or PDF." },
];
export const fillTpl = (body: string, s: R, name: string) => body.replace(/{{(\w+)}}/g, (_, k) => ({ name, ref: s.ref, from: s.pol, to: s.pod, eta: fmtDate(s.eta), link: `ternary.cargo/t/${s.ref}`, missing: "commercial invoice" } as R)[k] ?? `{{${k}}}`);
export function WhatsAppBubble({ text, from = "Ceylon Freight Lines", time = "12:41", mine = true }: { text: string; from?: string; time?: string; mine?: boolean }) {
  return <div className={cn("max-w-[85%] rounded-2xl px-3 py-2 text-sm shadow-sm", mine ? "ml-auto rounded-tr-sm bg-[#d9fdd3] text-[#111b21]" : "rounded-tl-sm bg-white text-[#111b21]")}>{!mine && <p className="text-xs font-semibold text-[#00704a]">{from}</p>}<p className="whitespace-pre-wrap">{text}</p><p className="mt-0.5 text-right text-[11px] text-[#4b5b63]">{time} {mine && "✓✓"}</p></div>;
}
export function PhonePreview({ children, title }: { children: React.ReactNode; title: string }) {
  return <div className="mx-auto w-[300px] overflow-hidden rounded-[2rem] border-[8px] border-foreground/90 bg-[#efeae2]" role="img" aria-label={`WhatsApp preview: ${title}`}><div className="flex items-center gap-2 bg-[#075e54] px-3 py-2 text-white"><div className="grid h-7 w-7 place-items-center rounded-full bg-white/20 text-xs">CF</div><div><p className="text-sm font-semibold">{title}</p><p className="text-[11px] opacity-80">mock preview · nothing is sent</p></div></div><div className="min-h-[260px] space-y-2 p-3">{children}</div></div>;
}
export function WhatsApp() {
  const { db, toast, log } = useStore(); const cust = db.customers as R[];
  const [opt, setOpt] = usePersist<Record<string, string>>("wa-optin", { "Singer Sri Lanka PLC": "2026-10-12" }); const [tpls, setTpls] = usePersist<Tpl[]>("wa-tpl", DEFAULT_TPL);
  const [sel, setSel] = useState("eta"); const t = tpls.find(x => x.id === sel) ?? tpls[0]; const s = (db.shipments as R[])[0];
  const [inbox, setInbox] = usePersist<{ id: number; from: string; text: string; at: string; job: string }[]>("wa-inbox", [{ id: 1, from: "Singer Sri Lanka PLC (+94 77 123 4567)", text: "Thanks. Can you deliver to our Wattala store instead?", at: "2026-11-01 09:12", job: "" }, { id: 2, from: "Abans PLC (+94 71 555 0101)", text: "Invoice photo attached for TC-SEA-24118", at: "2026-11-01 10:03", job: "" }, { id: 3, from: "Unknown (+94 76 000 1122)", text: "Where is my parcel?", at: "2026-11-01 11:20", job: "" }]);
  const jobs = (db.shipments as R[]).map(x => x.ref);
  return <Shell active="whatsapp" title="WhatsApp updates" subtitle="Send shipment updates customers can read on their phone. Mocked: no messages leave this prototype.">
    <div className="grid gap-4 xl:grid-cols-3">
      <Card><CardHeader title="Who agreed to WhatsApp" desc="Only customers who opted in get messages. Record when they agreed." /><ul className="divide-y divide-border">{cust.slice(0, 8).map(c => <li key={c.id} className="flex items-center gap-3 px-5 py-2.5 text-sm"><span className="flex-1 truncate">{c.name}</span>{opt[c.name] && <span className="text-xs text-muted-foreground">since {fmtDate(opt[c.name])}</span>}<input type="checkbox" role="switch" aria-label={`WhatsApp opt-in ${c.name}`} checked={!!opt[c.name]} onChange={e => { setOpt(o => { const n = { ...o }; if (e.target.checked) n[c.name] = today; else delete n[c.name]; return n; }); log(c.name, e.target.checked ? "WhatsApp opt-in recorded" : "WhatsApp opt-out recorded"); }} className="h-4 w-4" /></li>)}</ul></Card>
      <Card className="p-5"><p className="mb-2 font-semibold">Message templates</p><div className="mb-3 flex flex-wrap gap-1" role="group" aria-label="Templates">{tpls.map(x => <button key={x.id} aria-pressed={x.id === sel} onClick={() => setSel(x.id)} className={cn("rounded-lg border px-2.5 py-1 text-sm", x.id === sel ? "border-primary bg-accent text-primary" : "border-border")}>{x.name}</button>)}</div>
        <label className="block text-sm"><span className="text-xs text-muted-foreground">Template text · use {"{{name}} {{ref}} {{from}} {{to}} {{eta}} {{link}}"}</span><textarea aria-label="Template text" rows={5} value={t.body} onChange={e => setTpls(ts => ts.map(x => x.id === t.id ? { ...x, body: e.target.value } : x))} className="mt-1 w-full rounded-lg border border-input bg-card p-2 text-sm" /></label>
        <div className="mt-2 flex gap-2"><Button variant="outline" onClick={() => { setTpls(DEFAULT_TPL); toast("Templates reset"); }}>Reset</Button></div>
        <div className="mt-4"><PhonePreview title={s.consignee}><WhatsAppBubble text={fillTpl(t.body, s, s.consignee.split(" ")[0])} /></PhonePreview></div></Card>
      <Card><CardHeader title="Replies" desc="File each reply to the right job so the team sees it in the job history." /><ul className="divide-y divide-border" aria-label="WhatsApp replies">{inbox.map(m => <li key={m.id} className="space-y-2 px-5 py-3 text-sm"><div className="flex items-center gap-2"><Inbox size={14} className="text-muted-foreground" /><span className="font-medium">{m.from}</span><span className="ml-auto text-xs text-muted-foreground">{m.at.slice(11)}</span></div><p>{m.text}</p>
        <div className="flex items-center gap-2"><select aria-label={`File reply ${m.id} to job`} value={m.job} onChange={e => { const job = e.target.value; setInbox(ib => ib.map(x => x.id === m.id ? { ...x, job } : x)); if (job) { log(job, `WhatsApp reply from ${m.from}: “${m.text}”`, "WhatsApp"); toast(`Reply filed to ${job}`); } }} className="h-9 flex-1 rounded-lg border border-input bg-card px-2 text-sm"><option value="">File to job…</option>{jobs.map(j => <option key={j}>{j}</option>)}</select>{m.job ? <Badge tone="green">Filed</Badge> : <Badge tone="amber">New</Badge>}</div></li>)}</ul></Card></div>
  </Shell>;
}
export function ShareWhatsApp({ s }: { s: R }) {
  const { toast, log } = useStore(); const [open, setOpen] = useState(false); const [tpls] = usePersist<Tpl[]>("wa-tpl", DEFAULT_TPL); const [opt] = usePersist<Record<string, string>>("wa-optin", { "Singer Sri Lanka PLC": "2026-10-12" }); const [sel, setSel] = useState("eta");
  const t = tpls.find(x => x.id === sel) ?? tpls[0]; const ok = !!opt[s.consignee]; const text = fillTpl(t.body, s, s.consignee.split(" ")[0]);
  return <><Button variant="outline" onClick={() => setOpen(true)}><MessageCircle size={15} />Share update</Button>
    {open && <div className="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4" role="dialog" aria-modal="true" aria-label="Share on WhatsApp" onClick={() => setOpen(false)}><div className="w-full max-w-lg rounded-2xl bg-card p-5 shadow-xl" onClick={e => e.stopPropagation()}><p className="text-lg font-semibold">Share {s.ref} on WhatsApp</p><p className="mb-3 text-sm text-muted-foreground">To {s.consignee} · mocked, nothing is sent</p>
      <div className="mb-3 flex flex-wrap gap-1" role="group" aria-label="Template">{tpls.map(x => <button key={x.id} aria-pressed={x.id === sel} onClick={() => setSel(x.id)} className={cn("rounded-lg border px-2.5 py-1 text-sm", x.id === sel ? "border-primary bg-accent text-primary" : "border-border")}>{x.name}</button>)}</div>
      <PhonePreview title={s.consignee}><WhatsAppBubble text={text} /></PhonePreview>
      {!ok && <p className="mt-3 text-sm text-warning" role="status">{s.consignee} hasn&apos;t opted in to WhatsApp. Record their consent on the <Link className="underline" href="/whatsapp">WhatsApp page</Link> first.</p>}
      <div className="mt-4 flex justify-end gap-2"><Button variant="ghost" onClick={() => setOpen(false)}>Cancel</Button><Button variant="outline" onClick={() => { navigator.clipboard?.writeText(text).catch(() => {}); toast("Message copied"); }}>Copy text</Button><Button disabled={!ok} onClick={() => { log(s.ref, `WhatsApp “${t.name}” sent to ${s.consignee} (mock)`, "WhatsApp"); toast(`Mock WhatsApp sent to ${s.consignee}`); setOpen(false); }}><Send size={15} />Send (mock)</Button></div></div></div>}</>;
}

/* ---------------- Finance ---------------- */
type Cost = { id: number; job: string; what: string; paidTo: string; ccy: "USD" | "LKR"; amount: number; markup: number; recharged: boolean };
type Credit = { id: string; inv: string; amount: number; reason: string; at: string };
export function Finance() {
  const { db, toast, log } = useStore(); const ships = db.shipments as R[]; const invs = db.invoices as R[];
  const [rate, setRate] = usePersist<number>("usd-lkr", 298.5); const [rateIn, setRateIn] = useState(""); const [costs, setCosts] = usePersist<Cost[]>("costs", [{ id: 1, job: "TC-SEA-24121", what: "Port handling (THC)", paidTo: "SLPA", ccy: "LKR", amount: 48500, markup: 0, recharged: false }, { id: 2, job: "TC-SEA-24121", what: "Ocean freight", paidTo: "Maersk", ccy: "USD", amount: 310, markup: 10, recharged: true }, { id: 3, job: "TC-SEA-24118", what: "Customs inspection fee", paidTo: "Sri Lanka Customs", ccy: "LKR", amount: 12000, markup: 0, recharged: false }]);
  const [credits, setCredits] = usePersist<Credit[]>("credits", []); const [cn_, setCn] = useState({ inv: invs[0]?.ref ?? "", amount: "", reason: "" }); const [nc, setNc] = useState({ job: ships[0]?.ref ?? "", what: "", paidTo: "", ccy: "LKR", amount: "", markup: "0" });
  const lkr = (c: { ccy: string; amount: number }) => c.ccy === "USD" ? c.amount * rate : c.amount;
  const profit = ships.slice(0, 8).map(s => { const rev = invs.filter(i => i.shipment === s.ref).reduce((a, i) => a + +i.amount, 0) - credits.filter(c => invs.find(i => i.ref === c.inv)?.shipment === s.ref).reduce((a, c) => a + c.amount, 0) + costs.filter(c => c.job === s.ref && c.recharged).reduce((a, c) => a + lkr(c) * (1 + c.markup / 100), 0); const cost = costs.filter(c => c.job === s.ref).reduce((a, c) => a + lkr(c), 0); return { ref: s.ref, rev, cost, p: rev - cost }; });
  const L = (n: number) => "LKR " + Math.round(n).toLocaleString("en-GB");
  return <Shell active="finance" title="Job money" subtitle="Recharge costs you paid for customers, raise credit notes, and see what each job really earns.">
    <div className="mb-4 grid gap-4 md:grid-cols-4"><Card className="p-4"><p className="text-xs font-medium uppercase text-muted-foreground">USD → LKR rate</p><p className="mt-1 text-[28px] font-semibold tabular-nums">{rate.toFixed(2)}</p><div className="mt-2 flex gap-2"><input aria-label="New USD to LKR rate" inputMode="decimal" placeholder="e.g. 300.25" value={rateIn} onChange={e => setRateIn(e.target.value)} className="h-9 w-full rounded-lg border border-input bg-card px-2 text-sm" /><Button variant="outline" disabled={!(+rateIn > 50 && +rateIn < 1000)} onClick={() => { log("Finance", `USD/LKR rate changed ${rate} → ${rateIn}`); setRate(+rateIn); setRateIn(""); toast("Exchange rate updated; job profit recalculated"); }}>Set</Button></div></Card>
      <Stat label="Costs to recharge" value={L(costs.filter(c => !c.recharged).reduce((a, c) => a + lkr(c), 0))} sub={`${costs.filter(c => !c.recharged).length} not yet on an invoice`} /><Stat label="Credit notes" value={String(credits.length)} sub={L(credits.reduce((a, c) => a + c.amount, 0))} /><Stat label="Profit (8 jobs)" value={L(profit.reduce((a, x) => a + x.p, 0))} tone="text-success" /></div>
    <div className="grid gap-4 xl:grid-cols-2"><Card><CardHeader title="Costs paid for customers" desc="Tick Recharge to add the cost, plus your markup, to the customer's bill." />
      <div className="relative overflow-x-auto" tabIndex={0}><table className="w-full text-sm" aria-label="Recharge costs"><thead><tr className="bg-muted text-left text-xs text-muted-foreground"><th className="px-3 py-2">Job</th><th className="px-3">Cost</th><th className="px-3 text-right">Amount</th><th className="px-3 text-right">Markup %</th><th className="px-3 text-right">Bill (LKR)</th><th className="px-3">Recharge</th></tr></thead><tbody>{costs.map(c => <tr key={c.id} className="border-b border-border"><td className="whitespace-nowrap px-3 py-2 font-mono text-xs">{c.job}</td><td className="px-3">{c.what}<span className="block text-xs text-muted-foreground">paid to {c.paidTo}</span></td><td className="whitespace-nowrap px-3 text-right tabular-nums">{c.ccy} {c.amount.toLocaleString("en-GB")}</td><td className="px-3 text-right"><input aria-label={`Markup ${c.what}`} inputMode="decimal" value={c.markup} onChange={e => setCosts(cs => cs.map(x => x.id === c.id ? { ...x, markup: +e.target.value || 0 } : x))} className="h-8 w-16 rounded border border-input bg-card px-1 text-right" /></td><td className="px-3 text-right tabular-nums">{Math.round(lkr(c) * (1 + c.markup / 100)).toLocaleString("en-GB")}</td><td className="px-3"><input type="checkbox" aria-label={`Recharge ${c.what}`} checked={c.recharged} onChange={e => { setCosts(cs => cs.map(x => x.id === c.id ? { ...x, recharged: e.target.checked } : x)); log(c.job, `${c.what} ${e.target.checked ? "recharged to customer" : "removed from recharge"}`); }} /></td></tr>)}</tbody></table></div>
      <div className="grid gap-2 border-t border-border p-4 sm:grid-cols-6"><select aria-label="Cost job" value={nc.job} onChange={e => setNc({ ...nc, job: e.target.value })} className={inp + " sm:col-span-2"}>{ships.map(s => <option key={s.ref}>{s.ref}</option>)}</select><input aria-label="Cost description" placeholder="What was paid" value={nc.what} onChange={e => setNc({ ...nc, what: e.target.value })} className={inp + " sm:col-span-2"} /><input aria-label="Paid to" placeholder="Paid to" value={nc.paidTo} onChange={e => setNc({ ...nc, paidTo: e.target.value })} className={inp + " sm:col-span-2"} /><select aria-label="Cost currency" value={nc.ccy} onChange={e => setNc({ ...nc, ccy: e.target.value })} className={inp}><option>LKR</option><option>USD</option></select><input aria-label="Cost amount" inputMode="decimal" placeholder="Amount" value={nc.amount} onChange={e => setNc({ ...nc, amount: e.target.value })} className={inp + " sm:col-span-2"} /><Button className="sm:col-span-3 justify-center" disabled={!nc.what || !(+nc.amount > 0)} onClick={() => { setCosts(cs => [...cs, { id: Date.now(), job: nc.job, what: nc.what, paidTo: nc.paidTo || "—", ccy: nc.ccy as "USD", amount: +nc.amount, markup: +nc.markup || 0, recharged: false }]); log(nc.job, `Cost added: ${nc.what} ${nc.ccy} ${nc.amount}`); toast("Cost added"); setNc({ ...nc, what: "", paidTo: "", amount: "" }); }}>Add cost</Button></div></Card>
      <Card><CardHeader title="Credit notes" desc="Reduce an invoice without deleting it. A reason is required." /><div className="grid gap-2 p-4 sm:grid-cols-3"><select aria-label="Credit invoice" value={cn_.inv} onChange={e => setCn({ ...cn_, inv: e.target.value })} className={inp}>{invs.map(i => <option key={i.ref}>{i.ref}</option>)}</select><input aria-label="Credit amount" inputMode="decimal" placeholder="Amount (LKR)" value={cn_.amount} onChange={e => setCn({ ...cn_, amount: e.target.value })} className={inp} /><input aria-label="Credit reason" placeholder="Reason (min 10 characters)" value={cn_.reason} onChange={e => setCn({ ...cn_, reason: e.target.value })} className={inp} />
        <Button className="justify-center sm:col-span-3" disabled={!(+cn_.amount > 0) || cn_.reason.trim().length < 10 || +cn_.amount > +(invs.find(i => i.ref === cn_.inv)?.amount ?? 0)} onClick={() => { const id = `CN-2026-${String(credits.length + 1).padStart(4, "0")}`; setCredits(c => [...c, { id, inv: cn_.inv, amount: +cn_.amount, reason: cn_.reason, at: today }]); log(cn_.inv, `Credit note ${id} for LKR ${cn_.amount}: ${cn_.reason}`); toast(`Credit note ${id} raised`); setCn({ ...cn_, amount: "", reason: "" }); }}>Raise credit note</Button></div>
        <ul className="divide-y divide-border border-t border-border" aria-label="Credit notes">{credits.length === 0 ? <li className="px-5 py-4 text-sm text-muted-foreground">No credit notes yet.</li> : credits.map(c => <li key={c.id} className="flex items-center gap-3 px-5 py-2.5 text-sm"><span className="font-mono text-xs">{c.id}</span><span className="flex-1">against {c.inv}: {c.reason}</span><span className="tabular-nums">{L(c.amount)}</span><Button variant="ghost" aria-label={`Download ${c.id}`} onClick={() => saveBlob(`${c.id}.pdf`, makePdf(`Credit note ${c.id}`, [`Against invoice: ${c.inv}`, `Date: ${fmtDate(c.at)}`, `Amount: ${L(c.amount)}`, `Reason: ${c.reason}`]))}><Download size={14} /></Button></li>)}</ul></Card>
      <Card className="xl:col-span-2"><CardHeader title="Profit by job" desc={`Revenue (invoices − credits + recharges) minus costs, at ${rate.toFixed(2)} LKR per USD`} /><div className="relative overflow-x-auto" tabIndex={0}><table className="w-full text-sm" aria-label="Job profit"><thead><tr className="bg-muted text-left text-xs text-muted-foreground"><th className="px-3 py-2">Job</th><th className="px-3 text-right">Revenue</th><th className="px-3 text-right">Cost</th><th className="px-3 text-right">Profit</th><th className="px-3">Margin</th></tr></thead><tbody>{profit.map(x => <tr key={x.ref} className="border-b border-border"><td className="whitespace-nowrap px-3 py-2 font-mono text-xs">{x.ref}</td><td className="px-3 text-right tabular-nums">{L(x.rev)}</td><td className="px-3 text-right tabular-nums">{L(x.cost)}</td><td className={cn("px-3 text-right font-medium tabular-nums", x.p < 0 ? "text-danger" : "text-success")}>{L(x.p)}</td><td className="px-3"><div className="h-2 w-32 rounded bg-muted"><div className={cn("h-2 rounded", x.p < 0 ? "bg-danger" : "bg-success")} style={{ width: `${x.rev ? Math.min(100, Math.abs(x.p / x.rev) * 100) : 0}%` }} /></div></td></tr>)}</tbody></table></div></Card></div>
  </Shell>;
}

/* ---------------- Evidence & claims ---------------- */
type Ph = { id: number; name: string; url: string; note: string; at: string; tag: string };
export function Evidence({ q }: { q: R }) {
  const { db, toast, log } = useStore(); const ref = q.ref ?? "TC-SEA-24121"; const s = (db.shipments as R[]).find(x => x.ref === ref) ?? (db.shipments as R[])[0];
  const [ph, setPh] = usePersist<Ph[]>(`evidence-${s.ref}`, []); const [claim, setClaim] = useState({ to: s.carrier, amount: "", what: "Crushed carton PKG-007, 2.6 kg short" }); const ref_ = useRef<HTMLInputElement>(null);
  const addFile = (f: File) => { const r = new FileReader(); r.onload = () => { setPh(p => [...p, { id: Date.now(), name: f.name, url: String(r.result), note: "", at: new Date().toISOString().slice(0, 16).replace("T", " "), tag: "Damage" }]); log(s.ref, `Photo added: ${f.name}`); }; r.readAsDataURL(f); };
  const sample = () => { const c = document.createElement("canvas"); c.width = 320; c.height = 220; const x = c.getContext("2d")!; x.fillStyle = "#c8a36b"; x.fillRect(0, 0, 320, 220); x.fillStyle = "#7a5a2e"; x.fillRect(40, 60, 240, 120); x.strokeStyle = "#3b2a12"; x.lineWidth = 4; x.beginPath(); x.moveTo(60, 70); x.lineTo(140, 150); x.lineTo(200, 90); x.stroke(); x.fillStyle = "#fff"; x.font = "bold 16px sans-serif"; x.fillText(`PKG-007 · ${s.ref}`, 50, 40); setPh(p => [...p, { id: Date.now(), name: `sample-${p.length + 1}.png`, url: c.toDataURL(), note: "Corner crushed on arrival", at: "2026-11-01 10:15", tag: "Damage" }]); log(s.ref, "Sample damage photo added"); };
  return <Shell active="evidence" title={`Photos & claims · ${s.ref}`} subtitle="Take photos of damage or shortages, add a note to each, then produce a claims pack for the carrier or insurer.">
    <div className="grid gap-4 lg:grid-cols-3"><Card className="lg:col-span-2 p-5"><div className="mb-4 flex flex-wrap gap-2"><Button onClick={() => ref_.current?.click()}><Camera size={15} />Take or add photo</Button><input ref={ref_} aria-label="Photo file" type="file" accept="image/*" capture="environment" multiple className="sr-only" onChange={e => Array.from(e.target.files ?? []).forEach(addFile)} /><Button variant="outline" onClick={sample}>Add sample photo</Button></div>
      {ph.length === 0 ? <div className="rounded-2xl border-2 border-dashed border-border p-10 text-center text-sm text-muted-foreground">No photos yet. On a phone, “Take or add photo” opens the camera.</div> :
        <ul className="grid gap-3 sm:grid-cols-2" aria-label="Evidence photos">{ph.map(p => <li key={p.id} className="overflow-hidden rounded-xl border border-border">{/* eslint-disable-next-line @next/next/no-img-element */}<img src={p.url} alt={p.note || p.name} className="h-40 w-full object-cover" /><div className="space-y-2 p-3 text-sm"><div className="flex items-center gap-2"><select aria-label={`Type for ${p.name}`} value={p.tag} onChange={e => setPh(x => x.map(y => y.id === p.id ? { ...y, tag: e.target.value } : y))} className="h-8 rounded-lg border border-input bg-card px-2 text-xs">{["Damage", "Shortage", "Wet", "Seal", "Other"].map(t => <option key={t}>{t}</option>)}</select><span className="text-xs text-muted-foreground">{fmtDate(p.at.slice(0, 10))} {p.at.slice(11)}</span><button aria-label={`Remove ${p.name}`} onClick={() => setPh(x => x.filter(y => y.id !== p.id))} className="ml-auto rounded p-1 text-muted-foreground hover:bg-muted"><Trash2 size={14} /></button></div><input aria-label={`Note for ${p.name}`} placeholder="What does this show?" value={p.note} onChange={e => setPh(x => x.map(y => y.id === p.id ? { ...y, note: e.target.value } : y))} className="h-9 w-full rounded-lg border border-input bg-card px-2" /></div></li>)}</ul>}</Card>
      <Card className="space-y-3 p-5"><p className="font-semibold">Claims pack</p><label className="block text-sm"><span className="text-xs text-muted-foreground">Claim against</span><input aria-label="Claim against" value={claim.to} onChange={e => setClaim({ ...claim, to: e.target.value })} className={inp} /></label><label className="block text-sm"><span className="text-xs text-muted-foreground">What happened</span><textarea aria-label="What happened" rows={3} value={claim.what} onChange={e => setClaim({ ...claim, what: e.target.value })} className="w-full rounded-lg border border-input bg-card p-2 text-sm" /></label><label className="block text-sm"><span className="text-xs text-muted-foreground">Amount claimed (LKR)</span><input aria-label="Amount claimed" inputMode="decimal" value={claim.amount} onChange={e => setClaim({ ...claim, amount: e.target.value })} className={inp} /></label>
        <Button className="w-full justify-center" disabled={!ph.length || !(+claim.amount > 0)} onClick={() => { textWithPhotosPdf(`Claims pack ${s.ref}`, [`Claim against: ${claim.to}`, `Date: ${fmtDate(today)}`, `Shipment: ${s.ref}  BL/AWB: ${s.doc}`, `Route: ${s.pol} -> ${s.pod}`, `Consignee: ${s.consignee}`, "", `What happened: ${claim.what}`, `Amount claimed: LKR ${(+claim.amount).toLocaleString("en-GB")}`, "", `Evidence (${ph.length} photo${ph.length === 1 ? "" : "s"}):`, ...ph.map((p, i) => ` ${i + 1}. [${p.tag}] ${p.name} - ${p.note || "no note"} (${p.at})`), "", "Photos are on the following pages. Prototype - illustrative data."], ph.map(p => ({ url: p.url, caption: `[${p.tag}] ${p.note || p.name} (${p.at})` }))).then(b => saveBlob(`claims-pack-${s.ref}.pdf`, b)); log(s.ref, `Claims pack generated against ${claim.to}`); toast("Claims pack downloaded"); }}><FileText size={15} />Generate claims pack (PDF)</Button>
        {(!ph.length || !(+claim.amount > 0)) && <p className="text-xs text-muted-foreground" role="status">Add at least one photo and an amount first.</p>}</Card></div>
  </Shell>;
}

/* ---------------- Audit log ---------------- */
export const PERM_ROLES = ["Admin", "Operations manager", "Tally clerk", "Viewer"];
export const canBulkDelete = (r: string) => r === "Admin";
export function AuditLog() {
  const { events } = useStore(); const [me, setMe] = usePersist<string>("perm-role", "Operations manager"); const [q, setQ] = useState(""); const [src, setSrc] = useState("All");
  const srcs = useMemo(() => ["All", ...Array.from(new Set(events.map(e => e.source)))], [events]);
  const list = events.filter(e => (src === "All" || e.source === src) && (!q || `${e.ref} ${e.text} ${e.actor}`.toLowerCase().includes(q.toLowerCase()))).slice().reverse();
  return <Shell active="audit" title="Audit log" subtitle="Every change across the account: who did what, when, and on which record.">
    <Card className="mb-4 flex flex-wrap items-center gap-3 p-4 text-sm"><ShieldCheck size={18} className="text-primary" /><label className="flex items-center gap-2">Signed in as<select aria-label="Signed-in permission" value={me} onChange={e => setMe(e.target.value)} className="h-9 rounded-lg border border-input bg-card px-2">{PERM_ROLES.map(r => <option key={r}>{r}</option>)}</select></label><span className="text-muted-foreground">{canBulkDelete(me) ? "You can bulk delete records." : "Only Admins can bulk delete. Deleting records, one at a time or in bulk, is for Admins only. Every delete and override is written here."}</span></Card>
    <Card><div className="flex flex-wrap gap-2 border-b border-border p-3"><input aria-label="Search audit log" placeholder="Search ref, action or person…" value={q} onChange={e => setQ(e.target.value)} className="h-9 min-w-[220px] flex-1 rounded-lg border border-input bg-card px-3 text-sm" /><select aria-label="Audit source" value={src} onChange={e => setSrc(e.target.value)} className="h-9 rounded-lg border border-input bg-card px-2 text-sm">{srcs.map(s => <option key={s}>{s}</option>)}</select><Button variant="outline" onClick={() => saveBlob("audit-log.csv", new Blob(["When,Who,Record,Action,Source\n" + list.map(e => [e.at, e.actor, e.ref, `"${e.text.replace(/"/g, "'")}"`, e.source].join(",")).join("\n")], { type: "text/csv" }))}><Download size={15} />CSV</Button></div>
      <div className="relative overflow-x-auto" tabIndex={0}><table className="w-full text-sm" aria-label="Audit entries"><thead><tr className="bg-muted text-left text-xs text-muted-foreground"><th className="px-3 py-2">When <span className="font-normal">({TZ_LABEL})</span></th><th className="px-3">Who</th><th className="px-3">Record</th><th className="px-3">What happened</th><th className="px-3">Source</th></tr></thead><tbody>{list.slice(0, 200).map(e => <tr key={e.id} className="border-b border-border"><td className="whitespace-nowrap px-3 py-2 tabular-nums">{fmtColombo(e.at)} <span className="text-[11px] text-muted-foreground">UTC+5:30</span></td><td className="whitespace-nowrap px-3">{e.actor}</td><td className="whitespace-nowrap px-3 font-mono text-xs">{e.ref}</td><td className="px-3">{e.text}</td><td className="px-3"><Badge>{e.source}</Badge></td></tr>)}</tbody></table></div><p className="p-3 text-xs text-muted-foreground">{list.length} entries</p></Card>
  </Shell>;
}

/* ---------------- Alerts ---------------- */
type Rule = { id: string; name: string; kind: "demurrage" | "eta"; threshold: number; email: boolean; wa: boolean; to: string; on: boolean };
export function Alerts() {
  const { db, toast, log } = useStore(); const [rules, setRules] = usePersist<Rule[]>("alerts", [{ id: "dd", name: "Demurrage: free days running out", kind: "demurrage", threshold: 2, email: true, wa: false, to: "ops@ceylonfreight.example", on: true }, { id: "eta", name: "ETA slips", kind: "eta", threshold: 1, email: true, wa: true, to: "+94 77 123 4567", on: true }]);
  const [prev, setPrev] = useState<Rule | null>(null); const s = (db.shipments as R[])[0];
  const set = (id: string, p: Partial<Rule>) => setRules(r => r.map(x => x.id === id ? { ...x, ...p } : x));
  const msg = (r: Rule) => r.kind === "demurrage" ? `${s.ref}: only ${r.threshold} free day(s) left at ${s.pod} before demurrage starts (est. USD 75/day). Arrange collection.` : `${s.ref}: arrival moved by more than ${r.threshold} day(s). New estimate ${fmtDate(s.eta)}.`;
  return <Shell active="alerts" title="Alerts" subtitle="Get warned before demurrage charges start or when an arrival date slips, by email or WhatsApp (mocked).">
    <div className="grid gap-4 lg:grid-cols-2">{rules.map(r => <Card key={r.id} className="space-y-3 p-5"><div className="flex items-center gap-2"><Bell size={16} className="text-primary" /><p className="flex-1 font-semibold">{r.name}</p><label className="flex items-center gap-2 text-sm">On<input type="checkbox" role="switch" aria-label={`${r.name} on`} checked={r.on} onChange={e => set(r.id, { on: e.target.checked })} /></label></div>
      <label className="block text-sm">{r.kind === "demurrage" ? "Warn when free days left are at or below" : "Warn when the arrival date moves by more than (days)"}<input aria-label={`Threshold ${r.name}`} inputMode="numeric" value={r.threshold} onChange={e => set(r.id, { threshold: Math.max(0, +e.target.value || 0) })} className={inp + " mt-1 w-28"} /></label>
      <div className="flex flex-wrap gap-4 text-sm"><label className="flex items-center gap-2"><input type="checkbox" aria-label={`Email ${r.name}`} checked={r.email} onChange={e => set(r.id, { email: e.target.checked })} />Email</label><label className="flex items-center gap-2"><input type="checkbox" aria-label={`WhatsApp ${r.name}`} checked={r.wa} onChange={e => set(r.id, { wa: e.target.checked })} />WhatsApp</label></div>
      <label className="block text-sm">Send to<input aria-label={`Recipients ${r.name}`} value={r.to} onChange={e => set(r.id, { to: e.target.value })} className={inp + " mt-1"} /></label>
      <div className="flex gap-2"><Button variant="outline" disabled={!r.email && !r.wa} onClick={() => { setPrev(r); log("Alerts", `Test alert “${r.name}” previewed (mock)`); }}>Preview test alert</Button><Button onClick={() => { toast(`Saved: ${r.name}`); log("Alerts", `Alert rule saved: ${r.name}`); }}>Save</Button></div></Card>)}</div>
    {prev && <Card className="mt-4 p-5" aria-label="Alert preview"><div className="mb-3 flex items-center"><p className="flex-1 font-semibold">Test alert preview (mocked, nothing sent)</p><Button variant="ghost" onClick={() => setPrev(null)}>Close</Button></div><div className="grid gap-4 md:grid-cols-2">{prev.email && <div className="rounded-xl border border-border p-4 text-sm"><p className="text-xs text-muted-foreground">To: {prev.to}</p><p className="font-semibold">[Ternary Cargo] {prev.name}</p><p className="mt-2">{msg(prev)}</p></div>}{prev.wa && <PhonePreview title="Ternary alerts"><WhatsAppBubble mine={false} from="Ternary alerts" text={msg(prev)} /></PhonePreview>}</div></Card>}
  </Shell>;
}

/* ---------------- Help booklet ---------------- */
export const INCOTERMS: [string, string, string][] = [
  ["EXW", "Ex Works", "The buyer collects from your factory and pays for everything after that, including export customs."],
  ["FCA", "Free Carrier", "You hand the goods, cleared for export, to the buyer's carrier at an agreed place."],
  ["FAS", "Free Alongside Ship", "You deliver next to the ship at the port. The buyer pays for loading and the sea trip."],
  ["FOB", "Free On Board", "You pay until the goods are loaded on the ship. The buyer pays the sea freight and insurance."],
  ["CFR", "Cost and Freight", "You pay the sea freight to the destination port; the risk passes to the buyer once loaded."],
  ["CIF", "Cost, Insurance and Freight", "Like CFR, but you also buy basic insurance for the buyer."],
  ["CPT", "Carriage Paid To", "You pay transport to a named place (any mode); risk passes at the first carrier."],
  ["CIP", "Carriage and Insurance Paid", "Like CPT, plus you buy wide insurance cover."],
  ["DAP", "Delivered At Place", "You deliver to the buyer's address, not unloaded. The buyer pays import duty."],
  ["DPU", "Delivered at Place Unloaded", "Like DAP, but you also unload at the destination."],
  ["DDP", "Delivered Duty Paid", "You deliver to the door and pay everything, including import duty and taxes."],
];
const CHAPTERS: [string, string, React.ReactNode][] = [
  ["incoterms", "1. Incoterms: who pays for what", <div key="i"><p className="mb-3">Incoterms are 11 short codes (rules from the International Chamber of Commerce) written on the quote and invoice. Each says where your cost and risk end and the buyer&apos;s begin.</p><table className="w-full text-sm"><thead><tr className="text-left text-xs text-muted-foreground"><th className="py-1">Code</th><th>Name</th><th>In plain words</th></tr></thead><tbody>{INCOTERMS.map(([c, n, d]) => <tr key={c} id={`inco-${c}`} className="border-t border-border align-top"><td className="py-2 pr-3 font-mono font-semibold">{c}</td><td className="pr-3">{n}</td><td>{d}</td></tr>)}</tbody></table><p className="mt-3 text-xs text-muted-foreground">Rule of thumb: E and F codes = the buyer arranges the main trip; C codes = you pay the main trip but risk passes early; D codes = you deliver.</p></div>],
  ["codes", "2. Barcodes and notices (SSCC, ASN)", <p key="c">Every pallet gets an <b>SSCC</b>: an 18-digit pallet barcode that stays the same from your factory to the buyer. The <b>ASN</b> (advance shipping notice) is the list of those pallets sent ahead, so the buyer can scan them in on arrival. In Ternary the packing list is your ASN.</p>],
  ["docs", "3. Shipping receipts (HBL, MBL, AWB)", <p key="d">The <b>HBL</b> (house bill of lading) is the receipt your forwarder gives you for your goods. The <b>MBL</b> is the shipping line&apos;s receipt to the forwarder for the whole container. By air the receipt is an <b>AWB</b> (air waybill).</p>],
  ["places", "4. Warehouses and unloading (CFS, devanning)", <p key="p">A <b>CFS</b> (container freight station) is a warehouse near the port where shared containers are packed and unpacked. <b>Devanning</b> simply means unloading a container and counting what came out.</p>],
  ["containers", "5. Container numbers and seals", <p key="n">A container number is 4 letters and 7 digits, e.g. MSKU 774120 6. The last digit is a check digit worked out from the others (ISO 6346), so a typing mistake is caught at once. Seals carry 2–4 letters and 5–10 digits, e.g. ML-5521093.</p>],
];
const B = "/booklet/Ternary-Cargo-Beginners-Booklet.pdf"; export const BOOKLET_SIZE = "6.3 MB"; // public/booklet file is 6,333,769 bytes
export function BookletLink({ page, label = `Beginner's booklet (PDF, ${BOOKLET_SIZE})` }: { page?: number; label?: string }) { return <a href={page ? `${B}#page=${page}` : B} target="_blank" rel="noopener" className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-card px-3 py-1.5 text-sm font-medium text-primary hover:bg-primary/5">📘 {label}</a>; }
export function HelpBooklet({ q }: { q: R }) {
  const ch = q.ch ?? "incoterms";
  return <Shell active="help" title="Help booklet" subtitle="Short chapters that explain the trade words used in Ternary, in plain English." actions={<BookletLink />}>
    <p className="mb-4 text-sm text-muted-foreground">Want the full guide? The 59-page <a className="text-primary underline" href={B} target="_blank" rel="noopener">Beginner&apos;s booklet (PDF, {BOOKLET_SIZE})</a> covers everything step by step. {ch === "incoterms" && <a className="text-primary underline" href={`${B}#page=27`} target="_blank" rel="noopener">Incoterms are chapter 8, from page 27.</a>} {<span className="text-xs">Large file ({BOOKLET_SIZE}): best on Wi-Fi.</span>}</p>
    <div className="grid gap-4 lg:grid-cols-4"><Card className="h-fit p-3"><nav aria-label="Chapters" className="space-y-1">{CHAPTERS.map(([k, t]) => <Link key={k} href={`/help?ch=${k}`} aria-current={ch === k ? "page" : undefined} className={cn("block rounded-lg px-3 py-2 text-sm no-underline", ch === k ? "bg-accent font-semibold text-primary" : "hover:bg-muted")}>{t}</Link>)}</nav><Link href="/glossary" className="mt-2 flex items-center gap-2 px-3 py-2 text-sm text-primary"><BookOpen size={14} />Full glossary</Link></Card>
      <Card className="p-6 lg:col-span-3"><h2 className="mb-3 text-xl font-semibold">{CHAPTERS.find(c => c[0] === ch)?.[1]}</h2><div className="text-sm leading-6">{CHAPTERS.find(c => c[0] === ch)?.[2]}</div></Card></div>
  </Shell>;
}
export function IncotermHelp({ value }: { value: string }) {
  const t = INCOTERMS.find(x => x[0] === value);
  return <p className="mt-1 text-xs text-muted-foreground" role="note">{t ? <><b>{t[0]} · {t[1]}:</b> {t[2]} </> : "Pick the rule agreed with the buyer. "}<Link href="/help?ch=incoterms" className="text-primary underline underline-offset-2">Which one? Read the Incoterms chapter</Link> · <a href={`${B}#page=27`} target="_blank" rel="noopener" className="text-primary underline underline-offset-2">Booklet chapter 8 (PDF, p27, {BOOKLET_SIZE})</a></p>;
}
